def make(i,prompt,opts,ans,exp,strat,steps,diff): return {"id":f"question-english-performance-2-iv-3-{i}","subject":"english","type":"single-choice","prompt":prompt,"options":[{"id":k,"text":v} for k,v in opts.items()],"knowledgeIds":[KG],"difficulty":diff,"answer":{"value":ans,"explanation":exp},"provenance":{"origin":"original","license":"All rights reserved","sourceUrl":SOURCES[0]["url"],"sourceLocator":"三份公開英文試題僅供能力方向研究；未複製原題、選項、文章或答案。","authoringNote":"依官方課綱 KG 與公開英文試題的教室溝通能力方向獨立編寫；待第二輪 AI／Terra 內容複核。"},"reviewStatus":"draft","updatedAt":"2026-09-09","lessonId":LESSON,"examPatternRefs":refs(),"solutionStrategy":strat,"solutionSteps":steps}
Q=[
make(1,"You forgot your pencil before a quiz. Which classroom sentence should you use?",{"A":"Could I borrow a pencil, please?","B":"Could I close the school?","C":"I will erase your lunch.","D":"Why is the pencil a teacher?"},"A","The student needs a pencil temporarily, so a polite request to borrow one fits the situation.","Identify the missing classroom object and choose a permission request that names the needed action.",["Notice the quiz requires a pencil.","Identify the needed action: use someone else's pencil temporarily.","Match that need with borrow.","Check Could I and please for polite permission.","Choose A because it solves the immediate classroom problem respectfully."],"easy"),
make(2,"You enter class after the bell. What should you say to the teacher?",{"A":"I'm sorry I'm late. May I come in?","B":"Give me the test immediately.","C":"Congratulations on my lateness.","D":"The bell is a sandwich."},"A","An apology followed by a request for permission to enter is appropriate after arriving late.","Combine the time problem with the respectful classroom action required next.",["Identify the problem: the bell has already rung.","Choose an apology for lateness.","Add a permission request to enter.","Reject demanding and nonsensical responses.","Select A because it handles both the mistake and the next action."],"easy"),
make(3,"The teacher wants students to discuss in groups of two. Which instruction is correct?",{"A":"Work in pairs.","B":"Please work in silence alone.","C":"Turn off your partners.","D":"Leave the lesson unfinished."},"A","A pair contains two people, so Work in pairs gives the requested grouping instruction.","Use the required group size to select the standard classroom command.",["Read the group-size condition: two students.","Recall that a pair means two people.","Match the condition with Work in pairs.","Reject alone and the commands that do not describe grouping.","Choose A and restate it as work two by two."],"easy"),
make(4,"You do not understand the math example. Which sentence appropriately asks the teacher for clarification?",{"A":"Could you explain the second step again?","B":"I explain the teacher tomorrow.","C":"Please hide the equation.","D":"The second step is a window."},"A","The student needs clarification, and asking the teacher to explain the second step again is specific and polite.","Match the learning difficulty with a targeted request for explanation.",["Identify the problem: the example is not understood.","Locate the missing information: the second step.","Choose a verb that requests clarification: explain.","Check could you and again for a polite repeat request.","Select A because it tells the teacher exactly what is needed."],"medium"),
make(5,"A classmate is presenting. What should you say to ask the class to stop talking?",{"A":"Please be quiet while she speaks.","B":"Please borrow her voice.","C":"Talk louder during the presentation.","D":"The presentation is a pencil."},"A","Asking classmates to be quiet helps the presenter be heard and is appropriate during a presentation.","Use the speaker's need for an attentive audience to choose a respectful behavior request.",["Identify the event: a classmate is presenting.","Infer the needed classroom behavior: listening quietly.","Choose Please be quiet as the direct instruction.","Reject borrowing, louder talking, and nonsense.","Select A because it protects the speaker's opportunity to present."],"easy"),
make(6,"You finish your worksheet early and need another task. Which question is most appropriate?",{"A":"What should I do next?","B":"Why should I break the worksheet?","C":"Can I leave everyone here?","D":"Who erased the future?"},"A","Asking What should I do next? requests the teacher's next instruction after finishing the assigned work.","Connect completion of the current task with a question about the next classroom step.",["Identify the current state: the worksheet is finished.","Identify the need: a new appropriate task.","Choose a question asking for the next instruction.","Reject destructive, unsafe, and meaningless choices.","Select A because it invites the teacher to assign the next step."],"easy"),
make(7,"During a lab, the teacher says, 'Do not touch the hot plate.' What should students do?",{"A":"Keep their hands away from it.","B":"Touch it quickly to test it.","C":"Carry it through the hallway.","D":"Pour water on every desk."},"A","Do not touch means keep hands away; this follows the safety instruction without adding an unsafe action.","Interpret the negative imperative as a safety boundary and choose the behavior that obeys it.",["Identify the object: the hot plate.","Read Do not touch as a prohibition.","Translate the prohibition into safe behavior: keep hands away.","Reject choices that touch, move, or misuse equipment.","Choose A because it directly follows the safety rule."],"medium"),
make(8,"A student wants to speak during a discussion. Which classroom expression should the student use?",{"A":"May I say something?","B":"I will interrupt everyone now.","C":"Please erase the discussion.","D":"My hand is a homework."},"A","May I say something? politely asks for a turn to speak during a discussion.","Match the discussion setting with a permission request that respects turn-taking.",["Identify the goal: contribute an idea.","Notice that other people may be speaking.","Choose a phrase that requests a turn politely.","Reject interruption and nonsensical statements.","Select A because it supports orderly discussion."],"easy"),
make(9,"The group has completed its poster. Which sentence should the recorder say before handing it to the teacher?",{"A":"We are ready to present our poster.","B":"We have not started the poster at all.","C":"Please remove the classroom from the poster.","D":"The recorder is under the alphabet."},"A","Completing the poster means the group can announce that it is ready to present it.","Use the completed-work clue to choose a statement about readiness for the next step.",["Identify the completed task: the group finished the poster.","Identify the next classroom action: present it.","Match both facts with We are ready.","Reject the statement that denies completion and the nonsensical choices.","Choose A because it accurately transitions to presentation."],"medium"),
make(10,"A classmate looks confused by the homework instructions. What is the most helpful classroom response?",{"A":"Let me show you the first example.","B":"You should stay confused.","C":"I will hide the instructions.","D":"The homework can speak for itself."},"A","Offering to show the first example gives the classmate concrete help without doing the whole assignment for them.","Identify the learning need and choose assistance that clarifies the first step.",["Notice the classmate is confused by the instructions.","Find a response that provides useful guidance.","Check that showing the first example addresses the confusion.","Reject discouraging, hiding, and impossible responses.","Select A because it is supportive and pedagogically appropriate."],"hard"),
]
